code_example:
#define VALUE 42

// Direct Stringification (#v)
#define S(v) #v

const char* literal = S(my_variable_name);
// Expands to "my_variable_name"

// Indirect Stringification (Force Expansion before #)
#define STR(v) #v
#define XSTR(v) STR(v)

const char* expanded_val = XSTR(VALUE);
// XSTR(VALUE) -> STR(42) -> "42"

// Typical use case: Logging/Debugging
#define ASSERT_VAR(v) if (!(v)) printf("Assertion failed: %s\n", #v)
